static int install_guest_entry_trace(uint32_t guest_va, const uint8_t *expected, size_t prologue_length,
    BlackGuestFunction wrapper, uint8_t **trampoline_out)
{
    uint8_t *target = (uint8_t *)(uintptr_t)black_resolve_guest_function(guest_va);
    uint8_t branch[8] = { 0xE9, 0, 0, 0, 0, 0x90, 0x90, 0x90 };
    uint8_t *trampoline;
    int32_t displacement;
    DWORD old_protection;
    if (!target || !expected || prologue_length < 6 || prologue_length > sizeof(branch) ||
        !wrapper || !trampoline_out || memcmp(target, expected, prologue_length) != 0) {
        trace_log("event=guest_entry_hook_failed guest=0x%08X reason=unexpected_prologue\n", guest_va);
        return 0;
    }
    trampoline = (uint8_t *)VirtualAlloc(NULL, prologue_length + 5, MEM_RESERVE | MEM_COMMIT, PAGE_EXECUTE_READWRITE);
    if (!trampoline) return 0;
    memcpy(trampoline, target, prologue_length);
    trampoline[prologue_length] = 0xE9;
    displacement = (int32_t)((uint32_t)(uintptr_t)(target + prologue_length) -
        (uint32_t)(uintptr_t)(trampoline + prologue_length + 5));
    memcpy(trampoline + prologue_length + 1, &displacement, sizeof(displacement));
    FlushInstructionCache(GetCurrentProcess(), trampoline, prologue_length + 5);
    displacement = (int32_t)((uint32_t)(uintptr_t)wrapper - (uint32_t)(uintptr_t)(target + 5));
    memcpy(branch + 1, &displacement, sizeof(displacement));
    if (!VirtualProtect(target, prologue_length, PAGE_EXECUTE_READWRITE, &old_protection)) {
        VirtualFree(trampoline, 0, MEM_RELEASE);
        return 0;
    }
    memcpy(target, branch, prologue_length);
    FlushInstructionCache(GetCurrentProcess(), target, prologue_length);
    VirtualProtect(target, sizeof(branch), old_protection, &old_protection);
    *trampoline_out = trampoline;
    trace_log("event=guest_entry_hook_installed guest=0x%08X host=0x%08X wrapper=0x%08X trampoline=0x%08X copied_bytes=%u\n",
        guest_va, (uint32_t)(uintptr_t)target, (uint32_t)(uintptr_t)wrapper,
        (uint32_t)(uintptr_t)trampoline, (unsigned)prologue_length);
    return 1;
}

static int install_game_execution_entry_traces(void)
{
    static const uint8_t guest_init_prologue[6] = { 0x55, 0x8B, 0xEC, 0x83, 0xE4, 0xF8 };
    static const uint8_t guest_render_setup_prologue[6] = { 0x55, 0x8B, 0xEC, 0x83, 0xE4, 0xF0 };
    static const uint8_t guest_state_gate_prologue[7] = { 0x51, 0x8B, 0x87, 0x78, 0x10, 0x02, 0x00 };
    static const uint8_t game_render_prologue[6] = { 0x55, 0x8B, 0xEC, 0x83, 0xE4, 0xF0 };
    if (!install_guest_entry_trace(0x000E1A00u, guest_init_prologue, sizeof(guest_init_prologue),
            black_trace_guest_init_entry, &black_guest_init_entry_trampoline)) return 0;
    if (!install_guest_entry_trace(0x0020BC40u, guest_render_setup_prologue, sizeof(guest_render_setup_prologue),
            (BlackGuestFunction)black_trace_guest_render_setup, &black_guest_render_setup_trampoline)) return 0;
    black_guest_render_setup_original = (BlackGuestRenderSetupFunction)black_guest_render_setup_trampoline;
    return install_guest_entry_trace(0x0020D930u, guest_state_gate_prologue, sizeof(guest_state_gate_prologue),
            black_trace_guest_state_gate, &black_guest_state_gate_trampoline) &&
        install_guest_entry_trace(0x001EE820u, game_render_prologue, sizeof(game_render_prologue),
            black_trace_game_render_entry, &black_game_render_entry_trampoline);
}

int main(void)
{
    HMODULE module = GetModuleHandleW(NULL);
    trace_file = fopen("boot_trace.log", "a");
    if (!black_pgraph_rdi_self_check()) { trace_log("event=setup_failure operation=black_pgraph_rdi_self_check\n"); return 14; }
    if (!AddVectoredExceptionHandler(1, trace_vectored_exception)) {
        trace_log("event=setup_failure operation=AddVectoredExceptionHandler win32_error=%lu\n", GetLastError());
        return 13;
    }
    black_xbox_thread_finished = CreateEventW(NULL, TRUE, FALSE, NULL);
    if (!black_xbox_thread_finished) {
        trace_log("event=setup_failure operation=CreateEvent win32_error=%lu\n", GetLastError());
        return 12;
    }
    guest_image = (uint8_t *)VirtualAlloc(NULL, BLACK_GUEST_IMAGE_SIZE, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);
    if (!guest_image) {
        trace_log("event=setup_failure operation=VirtualAlloc guest_base=0x%08X guest_size=0x%08X win32_error=%lu\n",
            BLACK_GUEST_IMAGE_BASE, BLACK_GUEST_IMAGE_SIZE, GetLastError());
        return 10;
    }
    trace_log("event=guest_image_address_space base=0x%08X size=0x%08X identity_mapping=%u\n",
        (uint32_t)(uintptr_t)guest_image, BLACK_GUEST_IMAGE_SIZE,
        (uint32_t)((uintptr_t)guest_image == BLACK_GUEST_IMAGE_BASE));
    black_xbox_mmio = (uint8_t *)VirtualAlloc(NULL, BLACK_XBOX_MMIO_SIZE, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);
    if (!black_xbox_mmio) { trace_log("event=setup_failure operation=VirtualAlloc_xbox_mmio win32_error=%lu\n", GetLastError()); goto setup_failure; }
    trace_log("event=xbox_mmio_shadow host=0x%08X guest_base=0xFD000000 size=0x01000000 semantics=shadow_only\n",
        (uint32_t)(uintptr_t)black_xbox_mmio);
    if (!load_xbe_header()) { trace_log("event=setup_failure operation=load_xbe_header\n"); goto setup_failure; }
    if (!initialize_xbox_thread_context(&black_xbox_main_context)) { trace_log("event=setup_failure operation=initialize_main_thread_context\n"); goto setup_failure; }
    if (!initialize_xbox_thread_context(&black_xbox_system_context)) { trace_log("event=setup_failure operation=initialize_system_thread_context\n"); goto setup_failure; }
    black_xbox_active_context = &black_xbox_main_context;
    {
        uint32_t thread_id = GetCurrentThreadId();
        memcpy(black_xbox_main_context.thread_metadata + 0x12Cu, &thread_id, sizeof(thread_id));
    }
    if (!patch_guest_operands(module)) { trace_log("event=setup_failure operation=patch_guest_operands\n"); goto setup_failure; }
    if (!install_d3d_state_update_trace()) { trace_log("event=setup_failure operation=install_d3d_state_update_trace\n"); goto setup_failure; }
    if (!install_game_execution_entry_traces()) { trace_log("event=setup_failure operation=install_game_execution_entry_traces\n"); goto setup_failure; }
    if (!install_d3d_create_device_hook()) { trace_log("event=setup_failure operation=install_d3d_create_device_hook\n"); goto setup_failure; }
    if (!patch_xbox_pgraph_register_writes()) { trace_log("event=setup_failure operation=patch_xbox_pgraph_register_writes\n"); goto setup_failure; }
    if (!patch_xbox_pgraph_interrupt_ack()) { trace_log("event=setup_failure operation=patch_xbox_pgraph_interrupt_ack\n"); goto setup_failure; }
    if (!patch_xbox_pmc_vblank_ack()) { trace_log("event=setup_failure operation=patch_xbox_pmc_vblank_ack\n"); goto setup_failure; }
    if (!patch_xbox_cache_flush()) { trace_log("event=setup_failure operation=patch_xbox_cache_flush\n"); goto setup_failure; }
    if (!patch_xbox_gpu_fence()) { trace_log("event=setup_failure operation=patch_xbox_gpu_fence\n"); goto setup_failure; }
    if (!patch_a394a_short_conditionals()) { trace_log("event=setup_failure operation=patch_a394a_short_conditionals\n"); goto setup_failure; }
    if (!install_xapi_init_heap_store_trace()) { trace_log("event=setup_failure operation=install_xapi_init_heap_store_trace\n"); goto setup_failure; }
    if (!install_a1c7a_trace()) { trace_log("event=setup_failure operation=install_a1c7a_trace\n"); goto setup_failure; }
    if (!install_a2df8_trace()) { trace_log("event=setup_failure operation=install_a2df8_trace\n"); goto setup_failure; }
    if (!install_a2f2a_trace()) { trace_log("event=setup_failure operation=install_a2f2a_trace\n"); goto setup_failure; }
    if (!install_rtlunwind_trace()) { trace_log("event=setup_failure operation=install_rtlunwind_trace\n"); goto setup_failure; }
    if (!install_host_rtlunwind_trace()) { trace_log("event=setup_failure operation=install_host_rtlunwind_trace\n"); goto setup_failure; }
    (void)install_host_ntcontinue_trace();
    if (!install_a39f1_trace()) { trace_log("event=setup_failure operation=install_a39f1_trace\n"); goto setup_failure; }
    if (!install_a39ec_trace()) { trace_log("event=setup_failure operation=install_a39ec_trace\n"); goto setup_failure; }
    if (!install_a3a31_trace()) { trace_log("event=setup_failure operation=install_a3a31_trace\n"); goto setup_failure; }
    if (!patch_xbox_tls_base_read()) { trace_log("event=setup_failure operation=patch_xbox_tls_base_read\n"); goto setup_failure; }
    if (!patch_xbox_thread_id_fs_read()) { trace_log("event=setup_failure operation=patch_xbox_thread_id_fs_read\n"); goto setup_failure; }
    if (!install_ceil_entry_trace()) { trace_log("event=setup_failure operation=install_ceil_entry_trace\n"); goto setup_failure; }
    if (!install_ceil_controlfp_block_trace()) { trace_log("event=setup_failure operation=install_ceil_controlfp_block_trace\n"); goto setup_failure; }
    if (!install_import_traps()) { trace_log("event=setup_failure operation=install_import_traps\n"); goto setup_failure; }

    BlackGuestFunction callback = black_resolve_guest_runtime_target(0x000259CB);
    BlackGuestFunction unknown = black_resolve_guest_runtime_target(0xDEADBEEF);
    trace_log("event=startup module_base=0x%08X guest_image=0x%08X guest_size=0x%08X entry_guest_va=0x00025A3F guest_data=header_rdata_data\n",
        (uint32_t)(uintptr_t)module, (uint32_t)(uintptr_t)guest_image, BLACK_GUEST_IMAGE_SIZE);
    trace_log("event=guest_function_map functions=%u callback_guest_va=0x000259CB callback_host=0x%08X unknown_resolves=%u map_self_check=%u\n",
        black_guest_function_count(), (uint32_t)(uintptr_t)callback, unknown != 0, black_guest_function_map_self_check());
    __try {
        xbe_entry_point();
    }
    __except (capture_exception(GetExceptionInformation())) {
        uint32_t stack[16] = { 0 };
        SIZE_T stack_bytes = 0;
        ReadProcessMemory(GetCurrentProcess(), (const void *)(uintptr_t)guest_exception_context.Esp,
            stack, sizeof(stack), &stack_bytes);
        trace_log("event=exception code=0x%08lX host_eip=0x%08lX access_type=%lu fault_address=0x%08lX last_import=%s last_import_call_rva=0x%08X\n",
            guest_exception_code, guest_exception_ip, guest_access_type, guest_fault_address,
            last_import_name ? last_import_name : "none", last_import_return_rva);
        trace_log("event=cpu_context eax=%08lX ebx=%08lX ecx=%08lX edx=%08lX esi=%08lX edi=%08lX ebp=%08lX esp=%08lX eflags=%08lX\n",
            guest_exception_context.Eax, guest_exception_context.Ebx, guest_exception_context.Ecx,
            guest_exception_context.Edx, guest_exception_context.Esi, guest_exception_context.Edi,
            guest_exception_context.Ebp, guest_exception_context.Esp, guest_exception_context.EFlags);
        trace_log("event=stack bytes_read=%lu words=", (unsigned long)stack_bytes);
        for (size_t i = 0; i < stack_bytes / sizeof(stack[0]); ++i) {
            trace_log("%s%08X", i ? "," : "", stack[i]);
        }
        trace_log("\n");
        VirtualFree(guest_image, 0, MEM_RELEASE);
        if (trace_file) fclose(trace_file);
        return 20;
    }

    trace_log("event=entry_returned\n");
    if (InterlockedCompareExchange(&black_xbox_thread_started, 0, 0)) {
        DWORD wait_result;
        trace_log("event=waiting_for_guest_system_thread\n");
        do {
            wait_result = WaitForSingleObject(black_xbox_thread_finished, 1000);
            if (wait_result == WAIT_TIMEOUT) sample_guest_system_thread();
        } while (wait_result == WAIT_TIMEOUT);
        if (wait_result != WAIT_OBJECT_0) trace_log("event=guest_system_thread_wait_failed error=%lu\n", GetLastError());
        trace_log("event=guest_system_thread_finished\n");
    }
    if (black_xbox_system_thread_handle) CloseHandle(black_xbox_system_thread_handle);
    VirtualFree(guest_image, 0, MEM_RELEASE);
    CloseHandle(black_xbox_thread_finished);
    if (trace_file) fclose(trace_file);
    return 0;

setup_failure:
    VirtualFree(guest_image, 0, MEM_RELEASE);
    return 11;
}
